import{_ as a,o as e,c as i,ag as n}from"./chunks/framework.CZxGLIO_.js";const k=JSON.parse('{"title":"Production deployment","description":"Run GooseForum with systemd and Caddy, and verify HTTPS, permissions and proxy settings.","frontmatter":{"title":"Production deployment","description":"Run GooseForum with systemd and Caddy, and verify HTTPS, permissions and proxy settings."},"headers":[],"relativePath":"en/docs/gooseforum/deployment/index.md","filePath":"en/docs/gooseforum/deployment/index.md"}'),t={name:"en/docs/gooseforum/deployment/index.md"};function l(o,s,p,r,h,d){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="production-deployment" tabindex="-1">Production deployment <a class="header-anchor" href="#production-deployment" aria-label="Permalink to &quot;Production deployment&quot;">​</a></h1><p>This example uses <strong>Linux, systemd and Caddy on the same host</strong>. It assumes a domain, a server and an installed Caddy. Adapt paths, users and domain names. These service files are recommended examples, not an installer shipped by GooseForum.</p><h2 id="stable-paths-and-service-identity" tabindex="-1">Stable paths and service identity <a class="header-anchor" href="#stable-paths-and-service-identity" aria-label="Permalink to &quot;Stable paths and service identity&quot;">​</a></h2><p>Place the executable, <code>config.toml</code> and <code>storage/</code> in <code>/opt/gooseforum</code>, running as a dedicated system account named <code>gooseforum</code>. Create the account and directory, extract the release there, and grant the service account the required read/write access. Do not expose configuration or databases through a web root.</p><p>Generate the initial configuration by running from that directory, stop the process, then edit the <strong>existing sections</strong>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;production&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Keep the existing secretKey; do not replace the entire file with this excerpt.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://forum.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5234</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trustedProxies = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stdout&quot;</span></span></code></pre></div><p>TOML sections cannot be declared twice. Merge these values with existing database and other settings. Restrict <code>config.toml</code>, for example with <code>chmod 600 config.toml</code>, and ensure it belongs to the service account.</p><div class="warning custom-block"><p class="custom-block-title">Backend listening address</p><p>Production HTTP listens on all interfaces. Restrict external access to port <code>5234</code> using your firewall or security group, routing public traffic through the HTTPS proxy. <code>server.url</code> does not change the listening address.</p></div><h2 id="configure-systemd" tabindex="-1">Configure systemd <a class="header-anchor" href="#configure-systemd" aria-label="Permalink to &quot;Configure systemd&quot;">​</a></h2><p>Save this example as <code>/etc/systemd/system/gooseforum.service</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=GooseForum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network-online.target</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Wants</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network-online.target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=gooseforum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=gooseforum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WorkingDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/gooseforum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/gooseforum/GooseForum serve</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RestartSec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UMask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0077</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre></div><p><code>WorkingDirectory</code> determines configuration and relative data paths. The user must be able to access databases, logs and backups. Then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><h2 id="add-the-https-proxy" tabindex="-1">Add the HTTPS proxy <a class="header-anchor" href="#add-the-https-proxy" aria-label="Permalink to &quot;Add the HTTPS proxy&quot;">​</a></h2><p>Add this site block to your Caddyfile, replacing the domain:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forum.example.com {</span></span>
<span class="line"><span>    reverse_proxy 127.0.0.1:5234</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Point DNS at the server and allow ports 80 / 443 as required for certificate issuance and access. Use <a href="https://caddyserver.com/docs/command-line#caddy-validate" target="_blank" rel="noreferrer">Caddy&#39;s configuration validator</a> before reloading; see the <a href="https://caddyserver.com/docs/quick-starts/reverse-proxy" target="_blank" rel="noreferrer">official reverse-proxy guide</a>. A containerized or remote proxy requires corresponding changes to the backend address and <code>trustedProxies</code>.</p><h2 id="verify-the-deployment" tabindex="-1">Verify the deployment <a class="header-anchor" href="#verify-the-deployment" aria-label="Permalink to &quot;Verify the deployment&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:5234/api/forum/status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://forum.example.com/api/forum/status</span></span></code></pre></div><p>This checks HTTP access and the deployment-status path. It does not establish database, email or object-storage health. Test registration, login, posting, images, email links and third-party callbacks with the real domain.</p><p>For large upload failures, check application upload limits, HTTP timeouts and proxy limits. S3 direct uploads also require bucket CORS; see <a href="./../configuration/">configuration</a>.</p><h2 id="ongoing-operation" tabindex="-1">Ongoing operation <a class="header-anchor" href="#ongoing-operation" aria-label="Permalink to &quot;Ongoing operation&quot;">​</a></h2><p>Keep one service instance and establish the <a href="./../maintenance/">backup and upgrade</a> procedure. Restart after changing ports, databases, logging or the cache backend. File watching does not reinitialize every running subsystem.</p><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/app/console/serve.go" target="_blank" rel="noreferrer">HTTP listener</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/configuration.md" target="_blank" rel="noreferrer">Configuration</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/site-status.md" target="_blank" rel="noreferrer">Status endpoint</a>。</p>`,25)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
